const tags = [
  {tag:'G1BG1',semanticName:'PieceAtEntry',logicalAddress:'%I0.0',dataType:'Boolean',nodeId:'ns=3;s=\"G1BG1\"',evidenceStatus:'VALIDATED'},
  {tag:'G1BG2',semanticName:'PieceAtMiddle',logicalAddress:'%I0.1',dataType:'Boolean',nodeId:'ns=3;s=\"G1BG2\"',evidenceStatus:'VALIDATED'},
  {tag:'G1BG3',semanticName:'PieceAtExit',logicalAddress:'%I0.2',dataType:'Boolean',nodeId:'ns=3;s=\"G1BG3\"',evidenceStatus:'VALIDATED'},
  {tag:'C2BG1',semanticName:'SlideRetracted',logicalAddress:'%I0.4',dataType:'Boolean',nodeId:'ns=3;s=\"C2BG1\"',evidenceStatus:'VALIDATED'},
  {tag:'C2BG2',semanticName:'SlideExtended',logicalAddress:'%I0.5',dataType:'Boolean',nodeId:'ns=3;s=\"C2BG2\"',evidenceStatus:'VALIDATED'},
  {tag:'C2BG3',semanticName:'MagazineEmpty',logicalAddress:'%I0.6',dataType:'Boolean',nodeId:'ns=3;s=\"C2BG3\"',evidenceStatus:'VALIDATED'}
];
flow.set('validationTagByNodeId', Object.fromEntries(tags.map(t => [t.nodeId, t])));
return [tags.filter(t => t.evidenceStatus === 'VALIDATED' && t.nodeId !== 'FIELD_CONFIRMATION_REQUIRED').map(t => ({...msg, topic:t.nodeId, datatype:t.dataType, tagMetadata:t}))];

const byNodeId = flow.get('validationTagByNodeId') || {};
const meta = msg.tagMetadata || byNodeId[msg.topic];
if (!meta) { node.warn('Ignored sample without confirmed tag metadata: ' + msg.topic); return null; }
const current = msg.payload && msg.payload.value !== undefined ? msg.payload.value : msg.payload;
const key = 'previous::' + meta.tag;
const hadPrevious = flow.get(key + '::seen') === true;
const previous = flow.get(key);
flow.set(key, current);
flow.set(key + '::seen', true);
flow.set('lastOpcUaDataAt', Date.now());
const wasStale = flow.get('dataIsStale') === true;
flow.set('dataIsStale', false);
const outputs = [];
if (wasStale || flow.get('dataFreshRecorded') !== true) {
  flow.set('dataFreshRecorded', true);
  outputs.push({payload:{timestamp:new Date().toISOString(),cpsId:'cpslai1',testStep:flow.get('testStep') || 'BASELINE',event:'DATA_FRESH',source:'OPC_UA',validationMode:true}});
}
if (!hadPrevious || previous !== current) {
  outputs.push({payload:{timestamp:new Date().toISOString(),cpsId:'cpslai1',testStep:flow.get('testStep') || 'BASELINE',tag:meta.tag,candidateSemantic:meta.candidateSemantic || null,semanticName:meta.semanticName || null,previous:hadPrevious ? previous : null,current,nodeId:meta.nodeId,logicalAddress:meta.logicalAddress,dataType:meta.dataType,source:'OPC_UA',validationMode:true,evidenceStatus:'OBSERVED'}});
}
return [outputs];

const allowed = ['BASELINE','AUTO_MODE','MANUAL_MODE','PIECE_FLOW','START','RUNNING','STOP','RESET','MAGAZINE_EMPTY','EMERGENCY_STOP','ALARM'];
const step = String(msg.payload || '').trim().toUpperCase();
if (!allowed.includes(step)) { node.error('Invalid testStep: ' + step, msg); return null; }
flow.set('testStep', step);
node.status({fill:'blue',shape:'dot',text:step});
return null;

const allowed = new Set(['SF4','SF5','xMEnAuto','xMProcessBusy','running_sys','Manual_sys','STOP','ready_var','ALARMS','ALARM','bErrCodeMod1','bErrCodeMod2','bErrCodeMod3','bErrCodeSeq','bErrCodeOpMode']);
const meta = msg.payload;
if (!meta || !allowed.has(meta.tag)) { node.error('Unknown candidate tag', msg); return null; }
if (!meta.nodeId || meta.nodeId === 'FIELD_CONFIRMATION_REQUIRED') { node.error('Browse-confirmed nodeId is required; candidate was not subscribed', msg); return null; }
if (meta.evidenceStatus !== 'TO_VALIDATE') { node.error('Candidate must remain TO_VALIDATE during this experiment', msg); return null; }
const byNodeId = flow.get('validationTagByNodeId') || {};
byNodeId[meta.nodeId] = meta;
flow.set('validationTagByNodeId', byNodeId);
msg.topic = meta.nodeId;
msg.datatype = meta.dataType;
msg.tagMetadata = meta;
msg.payload = '';
return msg;

const text = String((msg.status && msg.status.text) || msg.status || msg.error || '').toLowerCase();
let state = null;
if (text.includes('connected') && !text.includes('disconnected')) state = 'OPCUA_CONNECTED';
if (text.includes('disconnected') || text.includes('error') || text.includes('reconnect')) state = 'OPCUA_DISCONNECTED';
if (!state || flow.get('opcuaConnectionEvent') === state) return null;
flow.set('opcuaConnectionEvent', state);
if (state === 'OPCUA_DISCONNECTED') { flow.set('dataIsStale', true); flow.set('dataFreshRecorded', false); }
msg.payload = {timestamp:new Date().toISOString(),cpsId:'cpslai1',testStep:flow.get('testStep') || 'BASELINE',event:state,source:'OPC_UA',validationMode:true};
return msg;

const last = flow.get('lastOpcUaDataAt');
const stale = !last || Date.now() - last > 10000;
if (!stale || flow.get('dataIsStale') === true) return null;
flow.set('dataIsStale', true);
flow.set('dataFreshRecorded', false);
msg.payload = {timestamp:new Date().toISOString(),cpsId:'cpslai1',testStep:flow.get('testStep') || 'BASELINE',event:'DATA_STALE',source:'OPC_UA',validationMode:true};
return msg;

const candidates = new Set(['SF4','SF5','xMEnAuto','xMProcessBusy','running_sys','Manual_sys','STOP','ready_var','ALARMS','ALARM','bErrCodeMod1','bErrCodeMod2','bErrCodeMod3','bErrCodeSeq','bErrCodeOpMode']);
const text = v => v == null ? null : (typeof v === 'string' ? v : (v.name || v.text || v.toString()));
const items = Array.isArray(msg.payload) ? msg.payload : [];
return [items.map(item => {
  const browseName = text(item.browseName);
  const nodeId = text(item.nodeId);
  const match = browseName && candidates.has(browseName.replace(/^\d+:/,''));
  return {payload:{timestamp:new Date().toISOString(),cpsId:'cpslai1',testStep:flow.get('testStep') || 'BASELINE',event:'OPCUA_BROWSE_OBSERVATION',browseName,nodeId,namespaceIndex:item.nodeId && item.nodeId.namespace !== undefined ? item.nodeId.namespace : null,dataType:item.dataType || null,candidateMatch:Boolean(match),evidenceStatus:'TO_VALIDATE',source:'OPC_UA',validationMode:true}};
})];
